#!/usr/bin/env node
/* LAVORA 6.0 patch — run from your project root:   node apply.mjs
   Adds: chat stickers/emoji/photos, edit + delete messages, login streak.
   Safe to re-run. Originals are saved to .lavora-backup/ first. */
import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const P = f => path.join(root, f);
const FILES = { "features.js": "", "features.css": "", "supabase-chat-policies.sql": "" };
const README_ADD = "";

for (const f of ["index.html", "script.js", "service-worker.js"]) {
  if (!fs.existsSync(P(f))) { console.error(`✖ ${f} not found. Run this from the LAVORA project folder.`); process.exit(1); }
}
const backupDir = P(".lavora-backup");
fs.mkdirSync(backupDir, { recursive: true });
const backup = f => { const dst = path.join(backupDir, f); if (!fs.existsSync(dst) && fs.existsSync(P(f))) fs.copyFileSync(P(f), dst); };
const dec = s => Buffer.from(s, "base64").toString("utf8");

let failed = false;
function edit(file, label, fn) {
  const src = fs.readFileSync(P(file), "utf8");
  try {
    const out = fn(src);
    if (out === src) { console.log(`• ${file}: ${label} (already applied)`); return; }
    backup(file); fs.writeFileSync(P(file), out); console.log(`✔ ${file}: ${label}`);
  } catch (e) { failed = true; console.error(`✖ ${file}: ${label} — ${e.message}`); }
}
const once = (src, needle, name) => {
  const i = src.indexOf(needle);
  if (i < 0) throw new Error(`anchor not found (${name})`);
  if (src.indexOf(needle, i + 1) >= 0) throw new Error(`anchor not unique (${name})`);
  return i;
};

// 1) new files
for (const [name, b64] of Object.entries(FILES)) {
  backup(name); fs.writeFileSync(P(name), dec(b64)); console.log(`✔ ${name}: written`);
}

// 2) index.html — load the new css + js
edit("index.html", "link features.css / features.js", s => {
  if (s.includes("features.js")) return s;
  const css = '<link rel="stylesheet" href="./style.css">';
  once(s, css, "style.css link");
  s = s.replace(css, css + '\n<link rel="stylesheet" href="./features.css">');
  const js = '<script src="./script.js"></script>';
  once(s, js, "script.js tag");
  return s.replace(js, js + '\n<script src="./features.js"></script>');
});

// 3) script.js — remove old public-chat block, add hooks
edit("script.js", "replace old public chat (moved to features.js)", s => {
  const a = "// ---------- Public chat ----------", b = "// ---------- Live studio ----------";
  if (!s.includes(a)) return s;           // already removed
  const i = once(s, a, "public chat start"), j = once(s, b, "live studio start");
  if (j < i) throw new Error("markers out of order");
  return s.slice(0, i) + "// ---------- Public chat: see features.js ----------\n\n" + s.slice(j);
});
edit("script.js", "streak hook on login", s => {
  if (s.includes("lavoraFeatures.onEnter")) return s;
  const n = "syncMyGamesFromProfile(); renderGames(); renderMyGames(); updateNotifBadge();";
  once(s, n, "finishEnter body");
  return s.replace(n, n + "\n  if (window.lavoraFeatures) lavoraFeatures.onEnter();");
});
edit("script.js", "cleanup hook on logout", s => {
  if (s.includes("lavoraFeatures.onLeave")) return s;
  const n = 'get("posts-list").replaceChildren(); get("chat-messages").replaceChildren();';
  once(s, n, "resetSession body");
  return s.replace(n, n + " if (window.lavoraFeatures) lavoraFeatures.onLeave();");
});

// 4) service worker — cache new files, bump version
edit("service-worker.js", "cache features + bump version", s => {
  if (s.includes("features.js")) return s;
  once(s, '"./seed.js",', "seed.js entry");
  s = s.replace('"./seed.js",', '"./seed.js",\n  "./features.js",\n  "./features.css",');
  return s.replace(/const CACHE_NAME = "lavora-v(\d+)";/, (_, n) => `const CACHE_NAME = "lavora-v${+n + 1}";`);
});

// 5) README
if (fs.existsSync(P("README.md"))) edit("README.md", "document new features", s => s.includes("## 6.0 changes") ? s : s.trimEnd() + "\n\n" + dec(README_ADD));

console.log(failed ? "\n⚠ Some edits failed. Nothing was half-written for those files; send me the error lines above." : "\nDone. Hard-refresh the app (the service worker cache version was bumped).\nFor edit/delete on Supabase, run supabase-chat-policies.sql once (see README).");
process.exit(failed ? 1 : 0);
